  // Sinkronisasi otomatis TitleCase, Uppercase, dan Wuku Baku ke MASTER_PAWUKON
  PAWUKON_LIST.forEach(item => {
    const no = item.no_wuku || item.no;
    const name = item.nama_wuku || item.name;
    if (no && name) {
      MASTER_PAWUKON[no] = item;
      MASTER_PAWUKON[String(no)] = item;
      MASTER_PAWUKON[name] = item;
      MASTER_PAWUKON[name.toLowerCase()] = item;
      MASTER_PAWUKON[name.toUpperCase()] = item;
      const titleName = name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();
      MASTER_PAWUKON[titleName] = item;
    }
  });

